use civ6_autotest_rs::startup_screen::{classify_png, MAX_PNG_BYTES};
use png::{BitDepth, ColorType};
use std::{io::Cursor, path::PathBuf};

fn unhex(s: &str) -> Vec<u8> {
    s.as_bytes()
        .chunks_exact(2)
        .map(|p| u8::from_str_radix(std::str::from_utf8(p).unwrap(), 16).unwrap())
        .collect()
}

fn decode(bytes: &[u8]) -> (usize, usize, Vec<u8>) {
    let mut reader = png::Decoder::new(Cursor::new(bytes)).read_info().unwrap();
    let mut p = vec![0; reader.output_buffer_size().unwrap()];
    let f = reader.next_frame(&mut p).unwrap();
    assert_eq!(f.color_type, ColorType::Rgb);
    (f.width as usize, f.height as usize, p)
}

fn encode(w: usize, h: usize, color: ColorType, pixels: &[u8]) -> Vec<u8> {
    let mut b = Vec::new();
    {
        let mut e = png::Encoder::new(&mut b, w as u32, h as u32);
        e.set_color(color);
        e.set_depth(BitDepth::Eight);
        e.write_header().unwrap().write_image_data(pixels).unwrap();
    }
    b
}

// Real antialiased captured pixels, independent of the classifier's binary template.
// Original owner diagnostic: D:/CC/Tools/civ6-live/pr86-startup-28-20261003.png.
// Its full 8710-byte PNG is retained as hex here to keep this change in the assigned files.
fn real_capture() -> Vec<u8> {
    unhex(REAL_CAPTURE_HEX)
}

fn scene(w: usize, h: usize, scale: f64, dx: i32, dy: i32) -> Vec<u8> {
    let (ow, _, original) = decode(&real_capture());
    let tw = (255.0 * scale).round() as usize;
    let th = (19.0 * scale).round() as usize;
    let ox = (w as i32 - tw as i32) / 2 + dx;
    let oy = (h as i32 - th as i32) / 2 + dy;
    let mut p = vec![0; w * h * 3];
    // White OS title strip should not contribute to client-body evidence.
    p[..w * 30 * 3].fill(240);
    for y in 0..th {
        for x in 0..tw {
            let sx = (x * 255 / tw).min(254);
            let sy = (y * 19 / th).min(18);
            let src = ((470 + sy) * ow + 600 + sx) * 3;
            let dest = (((oy as usize + y) * w) + ox as usize + x) * 3;
            p[dest..dest + 3].copy_from_slice(&original[src..src + 3]);
        }
    }
    p
}

fn recognized(b: &[u8]) -> serde_json::Value {
    let v = classify_png(b).unwrap();
    assert_eq!(v["status"], "recognized", "{v}");
    assert_eq!(v["pattern"], "civ6_initial_loading_english");
    assert!(v["score"].as_f64().unwrap() >= 0.82);
    v
}

fn unknown(b: &[u8]) {
    let v = classify_png(b).unwrap();
    assert_eq!(v["status"], "unknown", "{v}");
    assert_eq!(v["pattern"], serde_json::Value::Null);
}

#[test]
fn independent_real_capture_is_positive() {
    let v = recognized(&real_capture());
    assert_eq!(v["bounds"], serde_json::json!([600, 470, 854, 488]));
    assert_eq!(v["width"], 1456);
    assert_eq!(v["height"], 939);
}

#[test]
fn captured_glyphs_scale_and_translate_with_window_and_dpi() {
    for (w, h, s, dx, dy) in [
        (800, 600, 0.75, 8, 10),
        (1024, 768, 1.0, -16, 12),
        (1920, 1080, 1.5, 24, 20),
        (2560, 1440, 2.0, -32, 32),
        (3840, 2160, 3.0, 40, -30),
    ] {
        recognized(&encode(w, h, ColorType::Rgb, &scene(w, h, s, dx, dy)));
    }
}

#[test]
fn opaque_rgba_is_supported_and_transparency_refuses() {
    let (w, h, rgb) = decode(&real_capture());
    let mut rgba: Vec<u8> = rgb
        .chunks_exact(3)
        .flat_map(|p| [p[0], p[1], p[2], 255])
        .collect();
    recognized(&encode(w, h, ColorType::Rgba, &rgba));
    rgba[3] = 0;
    unknown(&encode(w, h, ColorType::Rgba, &rgba));
}

#[test]
fn black_and_near_black_have_no_positive_evidence() {
    for level in [0, 8, 12] {
        unknown(&encode(
            800,
            600,
            ColorType::Rgb,
            &vec![level; 800 * 600 * 3],
        ));
    }
}

#[test]
fn non_loading_centered_text_shape_refuses() {
    let (w, h) = (1024, 768);
    let mut p = vec![0; w * h * 3];
    // Distinct, independently drawn block glyphs; same bounding aspect as known text.
    for y in 375..394 {
        for x in 384..639 {
            if (x - 384) % 13 < 3 || y == 375 || y == 393 {
                p[(y * w + x) * 3..(y * w + x) * 3 + 3].fill(192);
            }
        }
    }
    unknown(&encode(w, h, ColorType::Rgb, &p));
}

#[test]
fn moved_missing_occluded_and_mirrored_glyphs_refuse() {
    unknown(&encode(
        1024,
        768,
        ColorType::Rgb,
        &scene(1024, 768, 1.0, 120, 0),
    ));
    let mut p = scene(1024, 768, 1.0, 0, 0);
    for y in 375..394 {
        for x in 450..520 {
            p[(y * 1024 + x) * 3..(y * 1024 + x) * 3 + 3].fill(0);
        }
    }
    unknown(&encode(1024, 768, ColorType::Rgb, &p));
    let mut p = scene(1024, 768, 1.0, 0, 0);
    for y in 0..768 {
        for x in 0..512 {
            for c in 0..3 {
                p.swap((y * 1024 + x) * 3 + c, (y * 1024 + 1023 - x) * 3 + c);
            }
        }
    }
    unknown(&encode(1024, 768, ColorType::Rgb, &p));
}

#[test]
fn additional_text_popup_color_or_occlusion_refuses() {
    for (x, y, color) in [
        (100, 120, [192, 192, 192]),
        (500, 200, [255, 255, 255]),
        (510, 384, [190, 80, 40]),
    ] {
        let mut p = scene(1024, 768, 1.0, 0, 0);
        p[(y * 1024 + x) * 3..(y * 1024 + x) * 3 + 3].copy_from_slice(&color);
        unknown(&encode(1024, 768, ColorType::Rgb, &p));
    }
}

#[test]
fn one_hidden_letter_or_punctuation_is_not_complete_loading_text() {
    // Keep the rest of the sentence, bbox and background unchanged.
    for (left, right) in [(59, 64), (97, 99), (249, 250)] {
        let (w, h, mut p) = decode(&real_capture());
        for y in 470..489 {
            for x in 600 + left..=600 + right {
                p[(y * w + x) * 3..(y * w + x) * 3 + 3].fill(0);
            }
        }
        unknown(&encode(w, h, ColorType::Rgb, &p));
    }
}

#[test]
fn malformed_truncated_crc_and_limits_fail_closed() {
    for b in [
        Vec::new(),
        b"not png".to_vec(),
        real_capture()[..100].to_vec(),
        real_capture()[..8700].to_vec(),
    ] {
        assert!(classify_png(&b).is_err());
    }
    let mut b = real_capture();
    b[29] ^= 1; // IHDR CRC
    assert!(classify_png(&b).is_err());
    assert!(classify_png(&vec![0; MAX_PNG_BYTES + 1]).is_err());
    for (w, h) in [(320, 240), (4097, 400), (640, 2561)] {
        // Mutate the real IHDR and repair its CRC, avoiding any large test allocation.
        let mut b = real_capture();
        b[16..20].copy_from_slice(&(w as u32).to_be_bytes());
        b[20..24].copy_from_slice(&(h as u32).to_be_bytes());
        let crc = crc32fast::hash(&b[12..29]);
        b[29..33].copy_from_slice(&crc.to_be_bytes());
        assert!(classify_png(&b).unwrap_err().message.contains("dimensions"));
    }
}

#[test]
fn unsupported_grayscale_and_sixteen_bit_fail_closed() {
    assert!(classify_png(&encode(800, 600, ColorType::Grayscale, &vec![0; 800 * 600])).is_err());
    let mut b = Vec::new();
    {
        let mut e = png::Encoder::new(&mut b, 800, 600);
        e.set_color(ColorType::Rgb);
        e.set_depth(BitDepth::Sixteen);
        e.write_header()
            .unwrap()
            .write_image_data(&vec![0; 800 * 600 * 6])
            .unwrap();
    }
    assert!(classify_png(&b).is_err());
}

// Owner's real menu/popup captures are deliberately not copied into the repository:
// these multi-MB game-art images are not needed for the portable positive fixture.
// Run with CIV6_STARTUP_NEGATIVE_ARTIFACTS=<.../live/tools/civ6-autotest/artifacts>.
// Normal portable tests still exercise independent non-loading and occlusion shapes.
#[test]
fn owners_real_menus_and_native_2k_popups_refuse_when_supplied() {
    let Some(root) = std::env::var_os("CIV6_STARTUP_NEGATIVE_ARTIFACTS") else {
        return;
    };
    let root = PathBuf::from(root);
    for path in [
        "main-15/main-menu-start1.png",
        "main-15/main-menu-start2.png",
        "main-15/main-menu-start3.png",
        "main-07/menu-after20.png",
        "main-08/menu-after20.png",
        "main-08/menu-after-close.png",
    ] {
        let b = std::fs::read(root.join(path)).unwrap();
        let v = classify_png(&b).unwrap();
        assert_eq!(v["status"], "unknown", "{path}: {v}");
        // main-07/08 are actual native 2K Account connection-issue dialogs,
        // not a synthetic popup or a claim about a 2K display resolution.
    }
}

const REAL_CAPTURE_HEX: &str = "";
